def parse_day(text):
    parts = text.split('-')
    year, month, day = int(parts[0]), int(parts[1]), int(parts[2])
    if month < 1 or month > 12:
        raise ValueError('bad month')
    if day < 1 or day > 31:
        raise ValueError('bad day')
    return (year, month, day)
